package cn.linkdeck.qa;
import android.app.*;import android.os.*;import android.net.nsd.*;import cn.linkdeck.adb.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Native NSD on a disposable emulator. Advertised sockets must never be contacted. */
public class Discovery13Checks extends Instrumentation {
 boolean lifecycleOnly;int passes;void check(boolean ok,String name){if(!ok)throw new AssertionError(name);passes++;Bundle b=new Bundle();b.putString("stream","PASS: "+name+"\n");sendStatus(0,b);}public void onCreate(Bundle b){super.onCreate(b);lifecycleOnly=b!=null&&"true".equals(b.getString("lifecycleOnly"));start();}
 public void onStart(){Bundle result=new Bundle();NsdManager manager=(NsdManager)getTargetContext().getSystemService("servicediscovery");List<NsdManager.RegistrationListener> registrations=new ArrayList<>();ServerSocket socket=null;LanDiscovery discovery=null,cancelled=null;
 try{socket=new ServerSocket(0);socket.setSoTimeout(250);CountDownLatch registered=new CountDownLatch(3);AtomicInteger failures=new AtomicInteger();
  for(String type:new String[]{"_adb._tcp.","_adb-tls-pairing._tcp.","_adb-tls-connect._tcp."}){NsdServiceInfo info=new NsdServiceInfo();info.setServiceName("LinkDeck-native-QA");info.setServiceType(type);info.setPort(socket.getLocalPort());NsdManager.RegistrationListener listener=new NsdManager.RegistrationListener(){public void onServiceRegistered(NsdServiceInfo i){registered.countDown();}public void onRegistrationFailed(NsdServiceInfo i,int e){failures.incrementAndGet();registered.countDown();}public void onServiceUnregistered(NsdServiceInfo i){}public void onUnregistrationFailed(NsdServiceInfo i,int e){}};registrations.add(listener);manager.registerService(info,NsdManager.PROTOCOL_DNS_SD,listener);}
  check(registered.await(20,TimeUnit.SECONDS)&&failures.get()==0,"three actual mDNS service types are registered");final List<Integer> discoveryErrors=Collections.synchronizedList(new ArrayList<>());final Set<String> found=Collections.synchronizedSet(new HashSet<>());final int expectedPort=socket.getLocalPort();CountDownLatch completed=new CountDownLatch(1);discovery=new LanDiscovery(getTargetContext(),new LanDiscovery.Listener(){public void error(int code){discoveryErrors.add(code);}public void found(String host,int port,String type){if(port==expectedPort)found.add(type);}public void done(int count){completed.countDown();}});final LanDiscovery first=discovery;runOnMainSync(()->first.start());check(completed.await(20,TimeUnit.SECONDS),"user discovery completes within its bounded interval");
  check(discoveryErrors.isEmpty(),"system accepts all discovery requests: "+discoveryErrors);if(!lifecycleOnly)for(String type:new String[]{"_adb._tcp","_adb-tls-pairing._tcp","_adb-tls-connect._tcp"}){boolean seen=false;for(String actual:found)if(actual.startsWith(type))seen=true;check(seen,"native discovery resolves "+type);}
  try{Socket unexpected=socket.accept();unexpected.close();throw new AssertionError("discovery automatically connected");}catch(SocketTimeoutException expected){check(true,"discovery sends no control socket connections");}
  AtomicInteger late=new AtomicInteger();CountDownLatch stopped=new CountDownLatch(1);cancelled=new LanDiscovery(getTargetContext(),new LanDiscovery.Listener(){public void found(String host,int port,String type){late.incrementAndGet();}public void done(int count){stopped.countDown();}});final LanDiscovery second=cancelled;runOnMainSync(()->{second.start();second.close();});check(stopped.await(20,TimeUnit.SECONDS)&&late.get()==0,"closing discovery ignores late resolutions and stops scanning");result.putString("stream",(lifecycleOnly?"DISCOVERY LIFECYCLE PASSED (resolution unverified): ":"NATIVE DISCOVERY PASSED: ")+passes+" checks.\n");finish(-1,result);
 }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));finish(0,result);}finally{if(discovery!=null)discovery.close();if(cancelled!=null)cancelled.close();for(NsdManager.RegistrationListener l:registrations)try{manager.unregisterService(l);}catch(Exception ignored){}if(socket!=null)try{socket.close();}catch(Exception ignored){}}}
}
